function l(a,e){const r=Math.max(0,a);if(r<=e.grace_minutes*60)return{amount:0,hours:0,graceApplied:!0,capApplied:!1,gross:0,fullDays:0};const t=Math.max(1,Math.ceil(r/3600)),s=t*e.hourly_cents;let c=s,n=0;if(e.daily_cap_cents>0){n=Math.floor(t/24);const u=t%24;c=Math.min(s,n*e.daily_cap_cents+Math.min(u*e.hourly_cents,e.daily_cap_cents))}return{amount:c,hours:t,graceApplied:!1,capApplied:c<s,gross:s,fullDays:n}}function o(a,e){return a<=e.grace_minutes*60?e.grace_minutes*60-a:3600-a%3600}export{l as c,o as s};
